import { createContextClient, verifyAuth } from "@supabase/server/core";
import { createClient } from "@supabase/supabase-js";
import { isAuditAcknowledged } from "./audit-contract";
import { PDFDocument } from "pdf-lib";

type WorkerEnv = Env & {
  SUPABASE_URL?: string;
  SUPABASE_PUBLISHABLE_KEY?: string;
  SUPABASE_SERVICE_ROLE_KEY?: string;
  GRADIPREP_TEST_RACE_BARRIER_SECRET?: string;
};

// Keep correlation IDs generated by this Worker associated with the original
// Request so the matching persisted audit row can be verified by the caller.
// A WeakMap avoids trusting a caller-supplied request ID or sharing state
// between concurrent requests.
const requestCorrelationIds = new WeakMap<Request, string>();

const localTestRaceBarrierTable = "gradioprep_test_race_barriers";

function localTestRaceBarrierClient(env: WorkerEnv) {
  if (!env.SUPABASE_URL || !env.SUPABASE_SERVICE_ROLE_KEY) return null;
  return createClient(env.SUPABASE_URL, env.SUPABASE_SERVICE_ROLE_KEY, {
    auth: { autoRefreshToken: false, persistSession: false, detectSessionInUrl: false },
  });
}
const localRaceSecretHeader = "x-gradioprep-test-race-secret";
const localRaceBarrierHeader = "x-gradioprep-test-race-barrier";
const localRacePointHeader = "x-gradioprep-test-race-point";

type ProtectedReadAuditAction =
  | "student_attempt_list_authorized"
  | "student_attempt_read_authorized"
  | "grader_attempt_queue_authorized"
  | "grader_attempt_read_authorized"
  | "student_submission_list_authorized"
  | "student_submission_read_authorized"
  | "grader_submission_queue_authorized"
  | "grader_submission_read_authorized"
  | "owner_submission_queue_authorized"
  | "staff_invitations_listed"
  | "private_qa_records_read";

type PrivilegedWriteAuditAction =
  | "owner_role_revocation"
  | "owner_attempt_assignment"
  | "owner_submission_assignment"
  | "owner_submission_reassignment"
  | "owner_submission_transition"
  | "owner_private_qa_record_create"
  | "grader_assessment_draft_save"
  | "grader_assessment_feedback_publish"
  | "staff_submission_transcript_review"
  | "student_attempt_create"
  | "student_attempt_response_save"
  | "student_attempt_submit"
  | "student_assessment_submission_accept"
  | "staff_invitation_created"
  | "staff_invitation_revoked"
  | "student_submission_file_upload"
  | "owner_submission_file_cleanup"
  | "staff_attempt_timer_adjustment"
  | "student_timed_attempt_assessment_link";

type PrivilegedWriteFailureCategory =
  | "resource_not_found"
  | "state_conflict"
  | "validation_failed"
  | "last_owner_protected"
  | "capacity_unavailable"
  | "operation_failed";

type AppRole = "student" | "guardian" | "grader" | "admin" | "owner";

const APP_ROLES: readonly AppRole[] = [
  "student",
  "guardian",
  "grader",
  "admin",
  "owner",
];

interface RoleRevocationRequest {
  target_user_id: string;
  role: AppRole;
  reason: string;
}

const jsonHeaders = {
  "Content-Type": "application/json; charset=utf-8",
  "Cache-Control": "no-store",
  "X-Content-Type-Options": "nosniff",
  "Referrer-Policy": "no-referrer",
};

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: jsonHeaders,
  });
}

function hasLocalTestRaceAccess(request: Request, env: WorkerEnv): boolean {
  const secret = env.GRADIPREP_TEST_RACE_BARRIER_SECRET;
  return new URL(request.url).hostname === "127.0.0.1" &&
    typeof secret === "string" &&
    secret.length >= 32 &&
    request.headers.get(localRaceSecretHeader) === secret;
}

async function handleLocalTestRaceBarrierControl(
  request: Request,
  env: WorkerEnv,
): Promise<Response | null> {
  const match = new URL(request.url).pathname.match(
    /^\/api\/__test\/race-barriers\/([0-9a-f-]{36})(\/release)?$/i,
  );
  if (!match) return null;
  if (!hasLocalTestRaceAccess(request, env)) {
    return jsonResponse({ error: "not_found" }, 404);
  }

  const barrierClient = localTestRaceBarrierClient(env);
  if (!barrierClient) return jsonResponse({ error: "not_found" }, 404);

  const barrierId = match[1].toLowerCase();
  const isRelease = Boolean(match[2]);
  if (!isRelease && request.method === "POST") {
    const body = await request.json().catch(() => null) as { expected_arrivals?: unknown } | null;
    const expectedArrivals = body?.expected_arrivals;
    if (expectedArrivals !== 1 && expectedArrivals !== 2) {
      return jsonResponse({ error: "invalid_test_barrier" }, 400);
    }

    const { error } = await barrierClient.from(localTestRaceBarrierTable).insert({
      id: barrierId,
      expected_arrivals: expectedArrivals,
      arrivals: 0,
      released: false,
    });
    if (error) return jsonResponse({ error: "test_barrier_unavailable" }, 503);
    return jsonResponse({ registered: true }, 201);
  }

  if (!isRelease && request.method === "GET") {
    const { data, error } = await barrierClient
      .from(localTestRaceBarrierTable)
      .select("arrivals,expected_arrivals")
      .eq("id", barrierId)
      .maybeSingle();
    if (error) return jsonResponse({ error: "test_barrier_unavailable" }, 503);
    if (!data) return jsonResponse({ error: "test_barrier_not_found" }, 404);
    return jsonResponse({
      arrivals: data.arrivals,
      expected_arrivals: data.expected_arrivals,
    });
  }

  if (isRelease && request.method === "POST") {
    const { data, error } = await barrierClient
      .from(localTestRaceBarrierTable)
      .update({ released: true })
      .eq("id", barrierId)
      .select("id")
      .maybeSingle();
    if (error) return jsonResponse({ error: "test_barrier_unavailable" }, 503);
    if (!data) return jsonResponse({ error: "test_barrier_not_found" }, 404);
    return jsonResponse({ released: true });
  }

  return jsonResponse({ error: "method_not_allowed" }, 405);
}

async function waitAtLocalTestRaceBarrier(
  request: Request,
  env: WorkerEnv,
  expectedPoint: string,
): Promise<Response | null> {
  const barrierId = request.headers.get(localRaceBarrierHeader);
  if (!barrierId || !hasLocalTestRaceAccess(request, env)) return null;
  if (request.headers.get(localRacePointHeader) !== expectedPoint) {
    return jsonResponse({ error: "test_barrier_point_mismatch" }, 400);
  }

  const barrierClient = localTestRaceBarrierClient(env);
  if (!barrierClient) return jsonResponse({ error: "test_barrier_unavailable" }, 503);

  const { data: accepted, error: arrivalError } = await barrierClient.rpc(
    "gradioprep_test_race_barrier_arrive",
    { p_barrier_id: barrierId.toLowerCase() },
  );
  if (arrivalError || accepted !== true) {
    return jsonResponse({ error: "test_barrier_unavailable" }, 409);
  }

  const deadline = Date.now() + 90_000;
  while (Date.now() < deadline) {
    const { data, error } = await barrierClient
      .from(localTestRaceBarrierTable)
      .select("released")
      .eq("id", barrierId.toLowerCase())
      .maybeSingle();
    if (error || !data) return jsonResponse({ error: "test_barrier_unavailable" }, 503);
    if (data.released) return null;
    await new Promise<void>((resolve) => setTimeout(resolve, 50));
  }

  return jsonResponse({ error: "test_barrier_timeout" }, 504);
}

function isValidDisplayName(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0 && value.trim().length <= 80;
}

function hasOnlyDisplayNameFields(value: unknown): value is { display_name: string } {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  return Object.keys(record).length === 1 && isValidDisplayName(record.display_name);
}

function isUuid(value: unknown): value is string {
  return typeof value === "string" &&
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value);
}

function hasOnlyRoleRevocationFields(value: unknown): value is RoleRevocationRequest {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  return Object.keys(record).length === 3 &&
    Object.keys(record).every((key) => ["target_user_id", "role", "reason"].includes(key)) &&
    isUuid(record.target_user_id) &&
    typeof record.role === "string" &&
    APP_ROLES.includes(record.role as AppRole) &&
    typeof record.reason === "string" &&
    record.reason.trim().length >= 3 &&
    record.reason.trim().length <= 240;
}

async function createCallerContext(request: Request, env: WorkerEnv) {
  if (!env.SUPABASE_URL || !env.SUPABASE_PUBLISHABLE_KEY) {
    throw new Error("Local Supabase environment is not configured.");
  }

  // Verify the bearer token and create the caller-scoped client. The separate
  // service-role client is reserved for audit ingestion and the narrowly scoped
  // Phase 1D file-storage lifecycle; it is never returned to browsers or used
  // for ordinary business-data reads or writes.
  const supabaseEnv = {
    url: env.SUPABASE_URL,
    publishableKeys: { default: env.SUPABASE_PUBLISHABLE_KEY },
    jwks: new URL("/auth/v1/.well-known/jwks.json", env.SUPABASE_URL),
  };
  const { data: auth, error } = await verifyAuth(request, {
    auth: "user",
    env: supabaseEnv,
  });

  if (error) return { data: null, error };
  if (!auth.token || !auth.userClaims?.id) {
    return { data: null, error: { status: 401, code: "missing_user_claims" } };
  }

  // Generate correlation metadata inside the trusted Worker. Both clients
  // attach the same ID so the database can correlate the operation and audit.
  const requestId = crypto.randomUUID();
  requestCorrelationIds.set(request, requestId);
  const supabase = createContextClient({
    auth: { token: auth.token },
    env: supabaseEnv,
    supabaseOptions: {
      global: {
        headers: { "x-request-id": requestId },
      },
    },
  });

  const serviceSupabase = env.SUPABASE_SERVICE_ROLE_KEY
    ? createClient(env.SUPABASE_URL, env.SUPABASE_SERVICE_ROLE_KEY, {
        auth: { autoRefreshToken: false, persistSession: false, detectSessionInUrl: false },
        global: { headers: { "x-request-id": requestId } },
      })
    : null;

  // Signature/expiry verification alone cannot detect a globally revoked
  // session until its JWT expires. Introspect the live session with GoTrue
  // before authorising protected Worker operations.
  const { data: currentUser, error: currentUserError } = await supabase.auth.getUser(auth.token);
  if (currentUserError || !currentUser.user || currentUser.user.id !== auth.userClaims.id) {
    const authUnavailable = Boolean(
      currentUserError &&
      (typeof currentUserError.status !== "number" || currentUserError.status >= 500)
    );
    return {
      data: null,
      error: {
        status: authUnavailable ? 503 : 401,
        code: authUnavailable ? "auth_service_unavailable" : "session_revoked",
      },
    };
  }

  // verifyAuth validates the JWT signature, issuer, audience and expiry.
  // Its normalized userClaims type omits the AAL field in some package versions,
  // so read assurance from the payload of that already-verified token.
  let assuranceLevel: "aal1" | "aal2" = "aal1";
  try {
    const encodedPayload = auth.token.split(".")[1];
    if (encodedPayload) {
      const base64 = encodedPayload.replace(/-/g, "+").replace(/_/g, "/");
      const padded = base64.padEnd(Math.ceil(base64.length / 4) * 4, "=");
      const binary = atob(padded);
      const bytes = Uint8Array.from(binary, character => character.charCodeAt(0));
      const verifiedClaims = JSON.parse(new TextDecoder().decode(bytes)) as Record<string, unknown>;
      assuranceLevel = verifiedClaims.aal === "aal2" ? "aal2" : "aal1";
    }
  } catch {
    // Fail closed: malformed or absent assurance claims remain AAL1.
  }

  return {
    data: {
      supabase,
      serviceSupabase,
      userId: auth.userClaims.id,
      assuranceLevel,
    },
    error: null,
  };
}

async function authenticatedMe(request: Request, env: WorkerEnv): Promise<Response> {
  if (!env.SUPABASE_URL || !env.SUPABASE_PUBLISHABLE_KEY) {
    return jsonResponse({
      error: "backend_not_configured",
      message: "Authentication is not connected to this public preview. Use the local development environment for synthetic account testing.",
    }, 503);
  }

  const { data: context, error } = await createCallerContext(request, env);

  if (error || !context) {
    return jsonResponse({
      error: "authentication_required",
      code: error?.code ?? "missing_user_claims",
      message: error?.code === "session_revoked"
        ? "This session has ended. Please sign in again."
        : "A valid signed-in account is required.",
    }, error?.status ?? 401);
  }

  const userId = context.userId;
  const [{ data: profile, error: profileError }, { data: roleRows, error: roleError }] = await Promise.all([
    context.supabase
      .from("profiles")
      .select("user_id, display_name, account_status, created_at")
      .eq("user_id", userId)
      .maybeSingle(),
    context.supabase
      .from("role_assignments")
      .select("role")
      .eq("user_id", userId)
      .is("revoked_at", null),
  ]);

  if (profileError || roleError) {
    return jsonResponse({
      error: "profile_unavailable",
      message: "The account profile could not be loaded. Please try again.",
    }, 500);
  }

  if (!profile || profile.account_status !== "active") {
    return jsonResponse({
      error: "account_unavailable",
      message: "This account is unavailable. Sign out or contact the project administrator.",
    }, 403);
  }

  return jsonResponse({
    user: { id: userId },
    profile,
    roles: (roleRows ?? []).map((row) => row.role),
  });
}

async function updateProfile(request: Request, env: WorkerEnv): Promise<Response> {
  if (!env.SUPABASE_URL || !env.SUPABASE_PUBLISHABLE_KEY) {
    return jsonResponse({
      error: "backend_not_configured",
      message: "Profile changes are unavailable in this public preview.",
    }, 503);
  }

  const contentLength = Number(request.headers.get("content-length") ?? "0");
  if (Number.isFinite(contentLength) && contentLength > 2_048) {
    return jsonResponse({ error: "request_too_large" }, 413);
  }

  let body: unknown;
  try {
    const raw = await request.text();
    if (raw.length > 2_048) return jsonResponse({ error: "request_too_large" }, 413);
    body = JSON.parse(raw);
  } catch {
    return jsonResponse({ error: "invalid_json" }, 400);
  }

  if (!hasOnlyDisplayNameFields(body)) {
    return jsonResponse({
      error: "invalid_profile_update",
      message: "Only a non-empty display_name of up to 80 characters can be changed.",
    }, 400);
  }

  const { data: context, error } = await createCallerContext(request, env);

  if (error || !context) {
    return jsonResponse({
      error: "authentication_required",
      code: error?.code ?? "missing_user_claims",
    }, error?.status ?? 401);
  }

  const { data: profile, error: updateError } = await context.supabase
    .from("profiles")
    .update({ display_name: body.display_name.trim() })
    .eq("user_id", context.userId)
    .select("user_id, display_name, account_status, created_at")
    .maybeSingle();

  if (updateError || !profile) {
    return jsonResponse({
      error: "account_unavailable",
      message: "This account is unavailable for profile changes.",
    }, 403);
  }

  return jsonResponse({ profile });
}

async function revokeRole(request: Request, env: WorkerEnv): Promise<Response> {
  if (!env.SUPABASE_URL || !env.SUPABASE_PUBLISHABLE_KEY) {
    return jsonResponse({
      error: "backend_not_configured",
      message: "Role administration is unavailable in this public preview.",
    }, 503);
  }

  const contentLength = Number(request.headers.get("content-length") ?? "0");
  if (Number.isFinite(contentLength) && contentLength > 2_048) {
    return jsonResponse({ error: "request_too_large" }, 413);
  }

  let body: unknown;
  try {
    const raw = await request.text();
    if (raw.length > 2_048) return jsonResponse({ error: "request_too_large" }, 413);
    body = JSON.parse(raw);
  } catch {
    return jsonResponse({ error: "invalid_json" }, 400);
  }

  if (!hasOnlyRoleRevocationFields(body)) {
    return jsonResponse({
      error: "invalid_role_revocation",
      message: "Provide a valid target_user_id, role and reason. Additional fields are not accepted.",
    }, 400);
  }

  const { data: context, error } = await createCallerContext(request, env);
  if (error || !context) {
    return jsonResponse({
      error: "authentication_required",
      code: error?.code ?? "missing_user_claims",
    }, error?.status ?? 401);
  }

  const { error: revokeError } = await context.supabase.rpc("revoke_role_assignment", {
    target_user_id: body.target_user_id,
    target_role: body.role,
    reason_text: body.reason.trim(),
  });

  if (revokeError) {
    const auditOutcome = classifyPrivilegedWriteError(revokeError);
    const audit = await auditPrivilegedWriteOutcome(
      context,
      "owner_role_revocation",
      body.target_user_id,
      auditOutcome.outcome,
      auditOutcome.failureCategory,
    );
    if (audit) return audit;
    if (revokeError.message === "mfa_required") {
      return jsonResponse({
        error: "mfa_required",
        message: "Verify a second factor before managing account roles.",
      }, 403);
    }
    if (revokeError.code === "42501") {
      return jsonResponse({
        error: "role_management_forbidden",
        message: "Only an authorised account owner can manage roles.",
      }, 403);
    }
    if (revokeError.code === "P0002") {
      return jsonResponse({ error: "role_assignment_not_found" }, 404);
    }
    if (revokeError.code === "23514") {
      return jsonResponse({
        error: "last_owner_protected",
        message: "The final active owner role cannot be revoked.",
      }, 409);
    }
    if (revokeError.code === "22023") {
      return jsonResponse({ error: "invalid_revocation_reason" }, 400);
    }
    return jsonResponse({
      error: "role_revocation_failed",
      message: "The role could not be revoked. Please try again.",
    }, 500);
  }

  return jsonResponse({ revoked: true });
}


interface StaffInvitationError {
  code?: string;
  message?: string;
}

interface StaffInvitationCreateRequest {
  email: string;
  role: "grader" | "admin";
}

function asRows(value: unknown): Record<string, unknown>[] {
  if (Array.isArray(value)) {
    return value.filter((row): row is Record<string, unknown> =>
      typeof row === "object" && row !== null && !Array.isArray(row)
    );
  }
  if (typeof value === "object" && value !== null && !Array.isArray(value)) {
    return [value as Record<string, unknown>];
  }
  return [];
}

async function readBoundedJson(
  request: Request,
  maxBytes = 2_048,
): Promise<{ ok: true; body: unknown } | { ok: false; response: Response }> {
  const contentLength = Number(request.headers.get("content-length") ?? "0");
  if (Number.isFinite(contentLength) && contentLength > maxBytes) {
    return { ok: false, response: jsonResponse({ error: "request_too_large" }, 413) };
  }
  try {
    const raw = await request.text();
    if (new TextEncoder().encode(raw).byteLength > maxBytes) {
      return { ok: false, response: jsonResponse({ error: "request_too_large" }, 413) };
    }
    return { ok: true, body: JSON.parse(raw) as unknown };
  } catch {
    return { ok: false, response: jsonResponse({ error: "invalid_json" }, 400) };
  }
}

function hasOnlyInvitationCreateFields(value: unknown): value is StaffInvitationCreateRequest {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  return Object.keys(record).length === 2 &&
    Object.keys(record).every((key) => ["email", "role"].includes(key)) &&
    typeof record.email === "string" &&
    record.email.trim().length >= 6 &&
    record.email.trim().length <= 320 &&
    /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(record.email.trim()) &&
    (record.role === "grader" || record.role === "admin");
}

function hasOnlyInvitationRevokeFields(value: unknown): value is { reason: string } {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  return Object.keys(record).length === 1 &&
    Object.keys(record)[0] === "reason" &&
    typeof record.reason === "string" &&
    record.reason.trim().length >= 3 &&
    record.reason.trim().length <= 80;
}

function hasOnlyInvitationAcceptFields(value: unknown): value is { token: string } {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  return Object.keys(record).length === 1 &&
    Object.keys(record)[0] === "token" &&
    typeof record.token === "string" &&
    /^[A-Za-z0-9_-]{43}$/.test(record.token);
}

function createInvitationToken(): string {
  const bytes = crypto.getRandomValues(new Uint8Array(32));
  const binary = Array.from(bytes, (byte) => String.fromCharCode(byte)).join("");
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}

async function hashInvitationToken(token: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(token));
  return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, "0")).join("");
}

function staffInvitationRpcError(error: StaffInvitationError): Response {
  const message = error.message ?? "";
  if (message === "mfa_required") {
    return jsonResponse({ error: message, message: "Verify a second factor before managing or accepting staff invitations." }, 403);
  }
  if (message === "staff_invitation_forbidden") {
    return jsonResponse({ error: message, message: "This account is not authorised to manage or accept staff invitations." }, 403);
  }
  if (message === "invitation_email_mismatch" || message === "invitation_email_unverified") {
    return jsonResponse({
      error: message,
      message: message === "invitation_email_mismatch"
        ? "Sign in with the verified email address to which this invitation was issued."
        : "Verify this account's email address before accepting the invitation.",
    }, 403);
  }
  if (message === "invitation_not_found") {
    return jsonResponse({ error: message, message: "This invitation link is invalid or no longer available." }, 404);
  }
  if (["invitation_expired", "invitation_revoked", "invitation_already_used", "invitation_not_pending"].includes(message)) {
    return jsonResponse({ error: message, message: "This invitation is no longer active. Ask the account owner for a new invitation." }, 410);
  }
  if (message === "invitation_rate_limited") {
    return jsonResponse({ error: message, message: "Too many invitations were created recently. Try again later." }, 429);
  }
  if (["invitation_already_pending", "invitation_role_already_active"].includes(message)) {
    return jsonResponse({ error: message, message: "A pending invitation or active role already exists for this email and role." }, 409);
  }
  if (message.startsWith("invalid_invitation_")) {
    return jsonResponse({ error: message, message: "The invitation details are invalid. Check the email, role and reason." }, 400);
  }
  return jsonResponse({ error: "staff_invitation_failed", message: "The invitation could not be processed. Please try again." }, 500);
}

async function listStaffInvitations(request: Request, env: WorkerEnv): Promise<Response> {
  if (!env.SUPABASE_URL || !env.SUPABASE_PUBLISHABLE_KEY) return jsonResponse({ error: "backend_not_configured" }, 503);
  const { data: context, error } = await createCallerContext(request, env);
  if (error || !context) {
    return jsonResponse({ error: "authentication_required", code: error?.code ?? "missing_user_claims" }, error?.status ?? 401);
  }
  const { data, error: listError } = await context.supabase.rpc("list_staff_invitations");
  if (listError) {
    const response = staffInvitationRpcError(listError);
    const authorizationDenied =
      listError.message === "staff_invitation_forbidden" ||
      listError.message === "mfa_required";
    const audit = await auditProtectedReadOutcome(
      context,
      "staff_invitations_listed",
      undefined,
      authorizationDenied ? "denied" : "failed",
      response,
    );
    return audit ?? response;
  }
  return jsonResponse({ invitations: asRows(data) });
}

async function createStaffInvitation(request: Request, env: WorkerEnv): Promise<Response> {
  if (!env.SUPABASE_URL || !env.SUPABASE_PUBLISHABLE_KEY) return jsonResponse({ error: "backend_not_configured" }, 503);
  const parsed = await readBoundedJson(request);
  if (!parsed.ok) return parsed.response;
  if (!hasOnlyInvitationCreateFields(parsed.body)) return jsonResponse({ error: "invalid_staff_invitation" }, 400);

  const { data: context, error } = await createCallerContext(request, env);
  if (error || !context) {
    return jsonResponse({ error: "authentication_required", code: error?.code ?? "missing_user_claims" }, error?.status ?? 401);
  }

  const token = createInvitationToken();
  const tokenHash = await hashInvitationToken(token);
  const { data, error: createError } = await context.supabase.rpc("create_staff_invitation", {
    p_email: parsed.body.email.trim().toLowerCase(),
    p_role: parsed.body.role,
    p_token_hash: tokenHash,
  });
  if (createError) {
    const auditOutcome = classifyPrivilegedWriteError(createError);
    const audit = await auditPrivilegedWriteOutcome(
      context,
      "staff_invitation_created",
      undefined,
      auditOutcome.outcome,
      auditOutcome.failureCategory,
    );
    if (audit) return audit;
    return staffInvitationRpcError(createError);
  }

  const invitation = asRows(data)[0];
  if (!invitation) return jsonResponse({ error: "staff_invitation_failed" }, 500);

  // Return the bearer token once in the URL fragment; fragments are not sent
  // in HTTP requests or Referer headers. The database stores only tokenHash.
  const invitationUrl = new URL("/account", new URL(request.url).origin);
  invitationUrl.hash = "staff-invite=" + token;
  return jsonResponse({ invitation, invite_url: invitationUrl.toString() }, 201);
}

async function revokeStaffInvitation(request: Request, env: WorkerEnv, invitationId: string): Promise<Response> {
  if (!env.SUPABASE_URL || !env.SUPABASE_PUBLISHABLE_KEY) return jsonResponse({ error: "backend_not_configured" }, 503);
  const parsed = await readBoundedJson(request);
  if (!parsed.ok) return parsed.response;
  if (!hasOnlyInvitationRevokeFields(parsed.body) || !isUuid(invitationId)) {
    return jsonResponse({ error: "invalid_staff_invitation_revocation" }, 400);
  }
  const { data: context, error } = await createCallerContext(request, env);
  if (error || !context) {
    return jsonResponse({ error: "authentication_required", code: error?.code ?? "missing_user_claims" }, error?.status ?? 401);
  }
  const { error: revokeError } = await context.supabase.rpc("revoke_staff_invitation", {
    p_invitation_id: invitationId,
    p_reason: parsed.body.reason.trim(),
  });
  if (revokeError) {
    const auditOutcome = classifyPrivilegedWriteError(revokeError);
    const audit = await auditPrivilegedWriteOutcome(
      context,
      "staff_invitation_revoked",
      invitationId,
      auditOutcome.outcome,
      auditOutcome.failureCategory,
    );
    if (audit) return audit;
    return staffInvitationRpcError(revokeError);
  }
  return jsonResponse({ revoked: true });
}

async function acceptStaffInvitation(request: Request, env: WorkerEnv): Promise<Response> {
  if (!env.SUPABASE_URL || !env.SUPABASE_PUBLISHABLE_KEY) return jsonResponse({ error: "backend_not_configured" }, 503);
  const parsed = await readBoundedJson(request, 512);
  if (!parsed.ok) return parsed.response;
  if (!hasOnlyInvitationAcceptFields(parsed.body)) return jsonResponse({ error: "invalid_staff_invitation" }, 400);
  const { data: context, error } = await createCallerContext(request, env);
  if (error || !context) {
    return jsonResponse({ error: "authentication_required", code: error?.code ?? "missing_user_claims" }, error?.status ?? 401);
  }
  const tokenHash = await hashInvitationToken(parsed.body.token);
  const barrierResponse = await waitAtLocalTestRaceBarrier(
    request, env, "staff_invitation_accept_before_rpc",
  );
  if (barrierResponse) return barrierResponse;
  const { data, error: acceptError } = await context.supabase.rpc("accept_staff_invitation", {
    p_token_hash: tokenHash,
  });
  if (acceptError) {
    if (acceptError.message !== "invitation_not_found") {
      const audit = await auditStaffInvitationAcceptanceFailure(context, tokenHash);
      if (audit) return audit;
    }
    return staffInvitationRpcError(acceptError);
  }
  const accepted = asRows(data)[0];
  if (!accepted || !["grader", "admin"].includes(String(accepted.accepted_role))) {
    return jsonResponse({ error: "staff_invitation_failed" }, 500);
  }
  return jsonResponse({ accepted: true, role: accepted.accepted_role });
}


type CallerContext = NonNullable<Awaited<ReturnType<typeof createCallerContext>>["data"]>;

function hasOnlyAttemptStartFields(value: unknown): value is { task_version_id: string } {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  return Object.keys(record).length === 1 &&
    Object.keys(record)[0] === "task_version_id" &&
    isUuid(record.task_version_id);
}

function hasOnlyAttemptResponseFields(value: unknown): value is { response_text: string } {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  return Object.keys(record).length === 1 &&
    Object.keys(record)[0] === "response_text" &&
    typeof record.response_text === "string" &&
    record.response_text.length <= 12_000;
}

type TimedAttemptAssessmentLinkRequest = {
  assessment_submission_id: string;
  idempotency_key: string;
};

function hasOnlyTimedAttemptAssessmentLinkFields(
  value: unknown,
): value is TimedAttemptAssessmentLinkRequest {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  return Object.keys(record).length === 2 &&
    Object.keys(record).every(key => ["assessment_submission_id", "idempotency_key"].includes(key)) &&
    isUuid(record.assessment_submission_id) &&
    isUuid(record.idempotency_key);
}

function hasOnlyAttemptAssignmentFields(value: unknown): value is { grader_user_id: string; reason: string } {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  return Object.keys(record).length === 2 &&
    Object.keys(record).every((key) => ["grader_user_id", "reason"].includes(key)) &&
    isUuid(record.grader_user_id) &&
    typeof record.reason === "string" &&
    record.reason.trim().length >= 3 &&
    record.reason.trim().length <= 240;
}

function hasOnlyAssessmentSubmissionFields(value: unknown): value is {
  task_version_id: string;
  idempotency_key: string;
  response_text: string;
} {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  return Object.keys(record).length === 3 &&
    Object.keys(record).every((key) =>
      ["task_version_id", "idempotency_key", "response_text"].includes(key)
    ) &&
    isUuid(record.task_version_id) &&
    isUuid(record.idempotency_key) &&
    typeof record.response_text === "string" &&
    record.response_text.trim().length > 0 &&
    record.response_text.length <= 12_000;
}

function hasOnlySubmissionAssignmentFields(value: unknown): value is { grader_user_id: string; reason: string } {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  return Object.keys(record).length === 2 &&
    Object.keys(record).every((key) => ["grader_user_id", "reason"].includes(key)) &&
    isUuid(record.grader_user_id) &&
    typeof record.reason === "string" &&
    record.reason.trim().length >= 3 &&
    record.reason.trim().length <= 240;
}

function hasOnlySubmissionTransitionFields(value: unknown): value is {
  target_status: "queued" | "withdrawn" | "closed";
  reason: string;
} {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  return Object.keys(record).length === 2 &&
    Object.keys(record).every(key => ["target_status", "reason"].includes(key)) &&
    ["queued", "withdrawn", "closed"].includes(String(record.target_status)) &&
    typeof record.reason === "string" &&
    record.reason.trim().length >= 3 &&
    record.reason.trim().length <= 240;
}

function hasOnlyPrivateQaRecordFields(value: unknown): value is {
  checks: Record<string, boolean | number | string>;
  status: "pending" | "passed" | "action_required";
  explanation: string;
  uncertainty?: string;
  reviewer_action: string;
} {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  const keys = Object.keys(record);
  if (!keys.includes("checks") || !keys.includes("status") ||
      !keys.includes("explanation") || !keys.includes("reviewer_action") ||
      keys.some(key => ![
        "checks", "status", "explanation", "uncertainty", "reviewer_action",
      ].includes(key))) return false;

  if (typeof record.checks !== "object" || record.checks === null ||
      Array.isArray(record.checks)) return false;
  const checks = record.checks as Record<string, unknown>;
  const entries = Object.entries(checks);
  if (entries.length < 1 || entries.length > 30 || JSON.stringify(checks).length > 8_192) {
    return false;
  }
  if (!entries.every(([key, item]) =>
    /^[a-z][a-z0-9_]{1,39}$/.test(key) &&
    ((typeof item === "boolean") ||
      (typeof item === "string" && item.length <= 200) ||
      (typeof item === "number" && Number.isFinite(item)))
  )) return false;

  if (!["pending", "passed", "action_required"].includes(String(record.status)) ||
      typeof record.explanation !== "string" ||
      record.explanation.trim().length < 5 ||
      record.explanation.length > 2_000 ||
      typeof record.reviewer_action !== "string" ||
      record.reviewer_action.trim().length < 3 ||
      record.reviewer_action.length > 1_000) return false;

  return record.uncertainty === undefined ||
    (typeof record.uncertainty === "string" && record.uncertainty.length <= 1_000);
}

function hasOnlyAssessmentDraftFields(value: unknown): value is {
  overall_feedback: string;
  change_reason?: string;
  criterion_results: Array<{ criterion_id: string; points_awarded: number; feedback: string }>;
} {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  const keys = Object.keys(record);
  if (!keys.includes("overall_feedback") || !keys.includes("criterion_results") ||
      keys.some((key) => !["overall_feedback", "change_reason", "criterion_results"].includes(key))) {
    return false;
  }
  if (typeof record.overall_feedback !== "string" ||
      record.overall_feedback.trim().length < 5 ||
      record.overall_feedback.length > 8000 ||
      !Array.isArray(record.criterion_results) ||
      record.criterion_results.length < 1 ||
      record.criterion_results.length > 30) return false;
  if (record.change_reason !== undefined &&
      (typeof record.change_reason !== "string" ||
       record.change_reason.trim().length < 3 ||
       record.change_reason.trim().length > 240)) return false;

  return record.criterion_results.every((item: unknown) => {
    if (typeof item !== "object" || item === null || Array.isArray(item)) return false;
    const result = item as Record<string, unknown>;
    return Object.keys(result).length === 3 &&
      ["criterion_id", "points_awarded", "feedback"].every((key) => key in result) &&
      isUuid(result.criterion_id) &&
      typeof result.points_awarded === "number" &&
      Number.isFinite(result.points_awarded) &&
      result.points_awarded >= 0 &&
      result.points_awarded <= 1000 &&
      Math.round(result.points_awarded * 100) === result.points_awarded * 100 &&
      typeof result.feedback === "string" &&
      result.feedback.trim().length >= 5 &&
      result.feedback.length <= 3000;
  });
}

type TranscriptReviewPage = {
  page_number: number;
  text: string;
  status: "digital_text" | "no_text_layer" | "teacher_transcribed";
};

function hasOnlyTranscriptReviewFields(value: unknown): value is {
  expected_version: number;
  pages: TranscriptReviewPage[];
  review_note: string;
} {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  if (Object.keys(record).length !== 3 ||
      !["expected_version", "pages", "review_note"].every(key => key in record) ||
      !Number.isInteger(record.expected_version) ||
      (record.expected_version as number) < 1 ||
      typeof record.review_note !== "string" ||
      record.review_note.trim().length < 3 ||
      record.review_note.trim().length > 240 ||
      !Array.isArray(record.pages) ||
      record.pages.length < 1 ||
      record.pages.length > 10) return false;

  let totalCharacters = 0;
  return record.pages.every((entry: unknown, index: number) => {
    if (typeof entry !== "object" || entry === null || Array.isArray(entry)) return false;
    const page = entry as Record<string, unknown>;
    if (Object.keys(page).length !== 3 ||
        !["page_number", "text", "status"].every(key => key in page) ||
        !Number.isInteger(page.page_number) ||
        page.page_number !== index + 1 ||
        typeof page.text !== "string" ||
        page.text.length > 12_000 ||
        (page.status !== "digital_text" &&
         page.status !== "no_text_layer" &&
         page.status !== "teacher_transcribed") ||
        (page.status === "no_text_layer" && page.text !== "") ||
        (page.status !== "no_text_layer" && !page.text.trim())) return false;
    totalCharacters += page.text.length;
    return totalCharacters <= 120_000;
  });
}

function hasOnlyEmptyObject(value: unknown): boolean {
  return typeof value === "object" && value !== null && !Array.isArray(value) &&
    Object.keys(value as Record<string, unknown>).length === 0;
}

type TimerAdjustmentReasonCategory =
  | "accessibility_accommodation"
  | "approved_extension"
  | "verified_platform_outage";

type AttemptTimerAdjustmentRequest =
  | { mode: "extended"; extension_seconds: number; reason_category: TimerAdjustmentReasonCategory }
  | { mode: "untimed"; reason_category: TimerAdjustmentReasonCategory };

function hasOnlyAttemptTimerAdjustmentFields(
  value: unknown,
): value is AttemptTimerAdjustmentRequest {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  const allowedReasons: readonly string[] = [
    "accessibility_accommodation", "approved_extension", "verified_platform_outage",
  ];
  if (typeof record.reason_category !== "string" || !allowedReasons.includes(record.reason_category)) return false;
  if (record.mode === "extended") {
    return Object.keys(record).length === 3 &&
      Object.keys(record).every(key => ["mode", "extension_seconds", "reason_category"].includes(key)) &&
      typeof record.extension_seconds === "number" &&
      Number.isInteger(record.extension_seconds) &&
      record.extension_seconds >= 60 &&
      record.extension_seconds <= 43_200;
  }
  if (record.mode === "untimed") {
    return Object.keys(record).length === 2 &&
      Object.keys(record).every(key => ["mode", "reason_category"].includes(key));
  }
  return false;
}

async function authenticatedCaller(request: Request, env: WorkerEnv) {
  if (!env.SUPABASE_URL || !env.SUPABASE_PUBLISHABLE_KEY) {
    return {
      context: null,
      response: jsonResponse({ error: "backend_not_configured" }, 503),
    };
  }
  const { data: context, error } = await createCallerContext(request, env);
  if (error || !context) {
    return {
      context: null,
      response: jsonResponse({
        error: "authentication_required",
        code: error?.code ?? "missing_user_claims",
      }, error?.status ?? 401),
    };
  }
  return { context, response: null };
}

async function requireActiveRole(context: CallerContext, role: AppRole): Promise<Response | null> {
  const { data, error } = await context.supabase
    .from("role_assignments")
    .select("id")
    .eq("user_id", context.userId)
    .eq("role", role)
    .is("revoked_at", null)
    .maybeSingle();
  if (error) return jsonResponse({ error: "authorization_unavailable" }, 503);
  if (!data) return jsonResponse({ error: "role_required" }, 403);
  return null;
}

async function requireAnyActiveRole(
  context: CallerContext,
  roles: readonly AppRole[],
): Promise<Response | null> {
  const { data, error } = await context.supabase
    .from("role_assignments")
    .select("role")
    .eq("user_id", context.userId)
    .in("role", [...roles])
    .is("revoked_at", null)
    .limit(1);
  if (error) return jsonResponse({ error: "authorization_unavailable" }, 503);
  if (!data || data.length === 0) return jsonResponse({ error: "role_required" }, 403);
  return null;
}

function requireAal2(context: CallerContext): Response | null {
  return context.assuranceLevel === "aal2"
    ? null
    : jsonResponse({
        error: "mfa_required",
        message: "Verify a second factor before accessing protected staff operations.",
      }, 403);
}

async function auditPrivilegedWriteOutcome(
  context: CallerContext,
  action: PrivilegedWriteAuditAction,
  targetId: string | undefined,
  outcome: "denied" | "failed",
  failureCategory?: PrivilegedWriteFailureCategory,
): Promise<Response | null> {
  if (!context.serviceSupabase) {
    return jsonResponse({ error: "privileged_write_audit_unavailable", message: "The privileged operation cannot be completed without its server-side audit service." }, 503);
  }
  const { data, error } = await context.serviceSupabase.rpc("record_worker_audit_outcome", {
    p_actor_id: context.userId, p_action: action, p_target_id: targetId ?? null,
    p_outcome: outcome, p_failure_category: failureCategory ?? null,
  });
  if (!isAuditAcknowledged(data, error)) {
    return jsonResponse({
      error: "privileged_write_audit_unavailable",
      message: "The privileged operation could not be safely completed because its audit outcome could not be recorded.",
    }, 503);
  }
  return null;
}

async function auditStaffInvitationAcceptanceFailure(
  context: CallerContext,
  tokenHash: string,
): Promise<Response | null> {
  const { data, error } = await context.supabase.rpc("audit_staff_invitation_acceptance_failure", {
    p_token_hash: tokenHash,
  });
  if (error || data !== true) {
    return jsonResponse({
      error: "staff_invitation_audit_unavailable",
      message: "The invitation attempt could not be safely completed because its audit outcome could not be recorded.",
    }, 503);
  }
  return null;
}

function classifyPrivilegedWriteError(error: { code?: string; message?: string }): {
  outcome: "denied" | "failed";
  failureCategory?: PrivilegedWriteFailureCategory;
} {
  const message = error.message ?? "";
  if (error.code === "42501" || message === "mfa_required" || message.endsWith("_forbidden")) {
    return { outcome: "denied" };
  }
  if (error.code === "P0002" || message.endsWith("_not_found") || message === "attempt_timer_session_missing") {
    return { outcome: "failed", failureCategory: "resource_not_found" };
  }
  if (message === "last_active_owner_protected") {
    return { outcome: "failed", failureCategory: "last_owner_protected" };
  }
  if (error.code === "22023" || message.startsWith("invalid_") || message === "grader_not_available") {
    return { outcome: "failed", failureCategory: "validation_failed" };
  }
  if ([
    "assessment_submission_not_assignable",
    "assessment_submission_not_reassignable",
    "assessment_assignment_not_found",
    "grader_already_assigned",
    "invalid_assessment_transition",
    "assessment_draft_required",
    "attempt_already_assigned",
    "attempt_not_submitted",
    "attempt_not_editable",
    "attempt_response_required",
    "submission_idempotency_conflict",
    "submission_transcript_version_conflict",
    "assessment_submission_not_reviewable",
    "attempt_not_adjustable",
    "attempt_task_version_mismatch",
    "timed_attempt_assessment_link_conflict",
    "timed_attempt_assessment_link_idempotency_conflict",
    "assessment_submission_not_linkable",
    "attempt_not_linkable",
  ].includes(message)) {
    return { outcome: "failed", failureCategory: "state_conflict" };
  }
  if (message === "submission_capacity_unavailable" || message === "submission_capacity_full" ||
      message === "invitation_rate_limited") {
    return { outcome: "failed", failureCategory: "capacity_unavailable" };
  }
  if ([
    "invitation_expired",
    "invitation_revoked",
    "invitation_already_used",
    "invitation_not_pending",
    "invitation_already_pending",
    "invitation_role_already_active",
  ].includes(message)) {
    return { outcome: "failed", failureCategory: "state_conflict" };
  }
  if (message.startsWith("invalid_invitation_")) {
    return { outcome: "failed", failureCategory: "validation_failed" };
  }
  return { outcome: "failed", failureCategory: "operation_failed" };
}

async function auditProtectedReadOutcome(
  context: CallerContext,
  action: ProtectedReadAuditAction,
  targetId: string | undefined,
  outcome: "success" | "denied" | "failed",
  _deniedResponse?: Response,
): Promise<Response | null> {
  if (!context.serviceSupabase) {
    return jsonResponse({ error: "protected_read_audit_unavailable", message: "The protected read cannot be completed without its server-side audit service." }, 503);
  }
  const { data, error } = await context.serviceSupabase.rpc("record_worker_audit_outcome", {
    p_actor_id: context.userId, p_action: action, p_target_id: targetId ?? null,
    p_outcome: outcome, p_failure_category: null,
  });
  if (!isAuditAcknowledged(data, error)) {
    return jsonResponse({
      error: "protected_read_audit_unavailable",
      message: "The protected read could not be safely completed because its audit outcome could not be recorded.",
    }, 503);
  }
  return null;
}

async function listLearnerAttempts(request: Request, env: WorkerEnv): Promise<Response> {
  const auth = await authenticatedCaller(request, env);
  if (!auth.context) return auth.response!;
  const roleDenied = await requireActiveRole(auth.context, "student");
  if (roleDenied) {
    const audit = await auditProtectedReadOutcome(
      auth.context, "student_attempt_list_authorized", undefined, "denied", roleDenied,
    );
    return audit ?? roleDenied;
  }

  const { data: attempts, error: attemptsError } = await auth.context.supabase
    .from("attempts")
    .select("id, learner_id, task_version_id, status, started_at, submitted_at, task_versions(task_code, title, version, expected_min_words, ideal_words, time_allowance_seconds, timer_policy_version)")
    .eq("learner_id", auth.context.userId)
    .order("created_at", { ascending: false })
    .order("id", { ascending: false });

  if (attemptsError) {
    const audit = await auditProtectedReadOutcome(
      auth.context, "student_attempt_list_authorized", undefined, "failed",
    );
    if (audit) return audit;
    return jsonResponse({ error: "attempts_unavailable" }, 500);
  }

  const { data: enrolments, error: enrolmentError } = await auth.context.supabase
    .from("course_enrolments")
    .select("pathway_id")
    .eq("learner_id", auth.context.userId)
    .eq("status", "active");
  if (enrolmentError) {
    const audit = await auditProtectedReadOutcome(
      auth.context, "student_attempt_list_authorized", undefined, "failed",
    );
    if (audit) return audit;
    return jsonResponse({ error: "attempts_unavailable" }, 500);
  }

  const pathways = [...new Set((enrolments ?? []).map(item => item.pathway_id))];
  let availableTasks: unknown[] = [];
  if (pathways.length > 0) {
    const { data: tasks, error: tasksError } = await auth.context.supabase
      .from("task_versions")
      .select("id, task_code, title, version, pathway_id, time_allowance_seconds, timer_policy_version, expected_min_words, ideal_words")
      .eq("release_state", "published")
      .eq("response_mode", "typed")
      .in("pathway_id", pathways)
      .order("title", { ascending: true });
    if (tasksError) {
      const audit = await auditProtectedReadOutcome(
        auth.context, "student_attempt_list_authorized", undefined, "failed",
      );
      if (audit) return audit;
      return jsonResponse({ error: "attempts_unavailable" }, 500);
    }
    availableTasks = tasks ?? [];
  }

  const audit = await auditProtectedReadOutcome(
    auth.context, "student_attempt_list_authorized", undefined, "success",
  );
  if (audit) return audit;
  return jsonResponse({ attempts: attempts ?? [], available_tasks: availableTasks });
}

async function createLearnerAttempt(request: Request, env: WorkerEnv): Promise<Response> {
  const parsed = await readBoundedJson(request, 512);
  if (!parsed.ok) return parsed.response;
  if (!hasOnlyAttemptStartFields(parsed.body)) {
    return jsonResponse({ error: "invalid_attempt_request" }, 400);
  }

  const auth = await authenticatedCaller(request, env);
  if (!auth.context) return auth.response!;
  const roleDenied = await requireActiveRole(auth.context, "student");
  if (roleDenied) {
    const audit = roleDenied.status === 403
      ? await auditPrivilegedWriteOutcome(
          auth.context, "student_attempt_create", parsed.body.task_version_id, "denied",
        )
      : null;
    return audit ?? roleDenied;
  }

  const { data: taskVersion, error: taskError } = await auth.context.supabase
    .from("task_versions")
    .select("id, pathway_id")
    .eq("id", parsed.body.task_version_id)
    .eq("release_state", "published")
    .eq("response_mode", "typed")
    .maybeSingle();
  if (taskError) {
    const audit = await auditPrivilegedWriteOutcome(
      auth.context, "student_attempt_create", parsed.body.task_version_id,
      "failed", "operation_failed",
    );
    if (audit) return audit;
    return jsonResponse({ error: "task_unavailable" }, 500);
  }
  if (!taskVersion) {
    const audit = await auditPrivilegedWriteOutcome(
      auth.context, "student_attempt_create", parsed.body.task_version_id, "denied",
    );
    if (audit) return audit;
    return jsonResponse({ error: "task_not_available" }, 404);
  }

  const { data: enrolment, error: enrolmentError } = await auth.context.supabase
    .from("course_enrolments")
    .select("id")
    .eq("learner_id", auth.context.userId)
    .eq("pathway_id", taskVersion.pathway_id)
    .eq("status", "active")
    .maybeSingle();
  if (enrolmentError) {
    const audit = await auditPrivilegedWriteOutcome(
      auth.context, "student_attempt_create", taskVersion.id, "failed", "operation_failed",
    );
    if (audit) return audit;
    return jsonResponse({ error: "enrolment_unavailable" }, 500);
  }
  if (!enrolment) {
    const audit = await auditPrivilegedWriteOutcome(
      auth.context, "student_attempt_create", taskVersion.id, "denied",
    );
    if (audit) return audit;
    return jsonResponse({ error: "task_not_available" }, 404);
  }

  const { data, error: createError } = await auth.context.supabase.rpc("create_attempt", {
    p_task_version_id: taskVersion.id,
  });

  if (createError) {
    const auditOutcome = classifyPrivilegedWriteError(createError);
    const audit = await auditPrivilegedWriteOutcome(
      auth.context, "student_attempt_create", taskVersion.id,
      auditOutcome.outcome, auditOutcome.failureCategory,
    );
    if (audit) return audit;
    if (createError.message === "attempt_creation_forbidden") {
      return jsonResponse({ error: "attempt_creation_forbidden" }, 403);
    }
    if (createError.message === "attempt_task_not_available") {
      return jsonResponse({ error: "task_not_available" }, 404);
    }
    return jsonResponse({ error: "attempt_creation_failed" }, 500);
  }

  const created = asRows(data)[0];
  if (!created) return jsonResponse({ error: "attempt_creation_failed" }, 500);
  return jsonResponse({
    attempt: {
      id: created.attempt_id,
      learner_id: created.learner_id,
      task_version_id: created.task_version_id,
      status: created.status,
      started_at: created.started_at,
      submitted_at: created.submitted_at,
    },
  }, 201);
}

async function readAttemptDetails(
  context: CallerContext,
  attemptId: string,
  includeLearnerTimer = false,
) {
  const { data: attempt, error: attemptError } = await context.supabase
    .from("attempts")
    .select("id, learner_id, task_version_id, status, started_at, submitted_at, task_versions(task_code, title, version, expected_min_words, ideal_words, time_allowance_seconds, timer_policy_version), attempt_responses(id, prompt_id, response_text, word_count, version, updated_at)")
    .eq("id", attemptId)
    .maybeSingle();

  if (attemptError || !attempt) {
    return { attempt: null, prompts: null, error: attemptError };
  }

  const { data: prompts, error: promptsError } = await context.supabase
    .from("task_version_prompts")
    .select("id, sequence, prompt_text")
    .eq("task_version_id", attempt.task_version_id)
    .order("sequence", { ascending: true });

  if (promptsError) {
    return { attempt: null, prompts: null, error: promptsError };
  }

  // Only the learner-owned route requests the timer. Assigned Graders receive
  // their authorised attempt detail, never the learner's private timer state.
  if (!includeLearnerTimer) {
    return { attempt, prompts: prompts ?? [], error: null };
  }

  const { data: timerData, error: timerError } = await context.supabase.rpc(
    "get_learner_attempt_timer",
    { p_attempt_id: attemptId },
  );
  const timer = asRows(timerData)[0];
  if (timerError || !timer) {
    return { attempt: null, prompts: null, error: timerError ?? new Error("attempt_timer_unavailable") };
  }

  return {
    attempt: { ...attempt, timer },
    prompts: prompts ?? [],
    error: null,
  };
}

async function getLearnerAttempt(request: Request, env: WorkerEnv, attemptId: string): Promise<Response> {
  const auth = await authenticatedCaller(request, env);
  if (!auth.context) return auth.response!;
  const roleDenied = await requireActiveRole(auth.context, "student");
  if (roleDenied) {
    const audit = await auditProtectedReadOutcome(
      auth.context, "student_attempt_read_authorized", attemptId, "denied", roleDenied,
    );
    return audit ?? roleDenied;
  }

  const result = await readAttemptDetails(auth.context, attemptId, true);
  if (result.error) {
    const audit = await auditProtectedReadOutcome(
      auth.context, "student_attempt_read_authorized", attemptId, "failed",
    );
    if (audit) return audit;
    return jsonResponse({ error: "attempt_unavailable" }, 500);
  }
  if (!result.attempt) {
    const audit = await auditProtectedReadOutcome(
      auth.context, "student_attempt_read_authorized", attemptId, "denied",
    );
    return audit ?? jsonResponse({ error: "attempt_not_found" }, 404);
  }
  const audit = await auditProtectedReadOutcome(
    auth.context, "student_attempt_read_authorized", attemptId, "success",
  );
  if (audit) return audit;
  return jsonResponse({ attempt: result.attempt, prompts: result.prompts });
}

async function saveAttemptResponse(
  request: Request,
  env: WorkerEnv,
  attemptId: string,
  promptId: string,
): Promise<Response> {
  const parsed = await readBoundedJson(request, 24_576);
  if (!parsed.ok) return parsed.response;
  if (!hasOnlyAttemptResponseFields(parsed.body)) {
    return jsonResponse({ error: "invalid_attempt_response" }, 400);
  }

  const auth = await authenticatedCaller(request, env);
  if (!auth.context) return auth.response!;
  const roleDenied = await requireActiveRole(auth.context, "student");
  if (roleDenied) {
    const audit = roleDenied.status === 403
      ? await auditPrivilegedWriteOutcome(
          auth.context, "student_attempt_response_save", attemptId, "denied",
        )
      : null;
    return audit ?? roleDenied;
  }

  const { data: attempt, error: attemptError } = await auth.context.supabase
    .from("attempts")
    .select("id, task_version_id, status")
    .eq("id", attemptId)
    .maybeSingle();
  if (attemptError) {
    const audit = await auditPrivilegedWriteOutcome(
      auth.context, "student_attempt_response_save", attemptId, "failed", "operation_failed",
    );
    if (audit) return audit;
    return jsonResponse({ error: "attempt_unavailable" }, 500);
  }
  if (!attempt) {
    const audit = await auditPrivilegedWriteOutcome(
      auth.context, "student_attempt_response_save", attemptId, "denied",
    );
    if (audit) return audit;
    return jsonResponse({ error: "attempt_not_found" }, 404);
  }
  if (attempt.status !== "in_progress") {
    const audit = await auditPrivilegedWriteOutcome(
      auth.context, "student_attempt_response_save", attemptId, "failed", "state_conflict",
    );
    if (audit) return audit;
    return jsonResponse({ error: "attempt_not_editable" }, 409);
  }

  const { data: prompt, error: promptError } = await auth.context.supabase
    .from("task_version_prompts")
    .select("id")
    .eq("id", promptId)
    .eq("task_version_id", attempt.task_version_id)
    .maybeSingle();
  if (promptError) {
    const audit = await auditPrivilegedWriteOutcome(
      auth.context, "student_attempt_response_save", attemptId, "failed", "operation_failed",
    );
    if (audit) return audit;
    return jsonResponse({ error: "prompt_unavailable" }, 500);
  }
  if (!prompt) {
    const audit = await auditPrivilegedWriteOutcome(
      auth.context, "student_attempt_response_save", attemptId, "failed", "validation_failed",
    );
    if (audit) return audit;
    return jsonResponse({ error: "prompt_not_found" }, 400);
  }

  const { data, error: saveError } = await auth.context.supabase.rpc("save_attempt_response", {
    p_attempt_id: attemptId,
    p_prompt_id: promptId,
    p_response_text: parsed.body.response_text,
  });

  if (saveError) {
    const auditOutcome = classifyPrivilegedWriteError(saveError);
    const audit = await auditPrivilegedWriteOutcome(
      auth.context, "student_attempt_response_save", attemptId,
      auditOutcome.outcome, auditOutcome.failureCategory,
    );
    if (audit) return audit;
    if (saveError.message === "attempt_not_found") return jsonResponse({ error: "attempt_not_found" }, 404);
    if (saveError.message === "attempt_not_editable") return jsonResponse({ error: "attempt_not_editable" }, 409);
    if (saveError.message === "attempt_response_forbidden") return jsonResponse({ error: "attempt_response_forbidden" }, 403);
    if (saveError.message === "invalid_attempt_response" || saveError.message === "invalid_attempt_prompt") {
      return jsonResponse({ error: "invalid_attempt_response" }, 400);
    }
    return jsonResponse({ error: "attempt_response_save_failed" }, 500);
  }

  const response = asRows(data)[0];
  if (!response) return jsonResponse({ error: "attempt_response_save_failed" }, 500);
  return jsonResponse({ response });
}

async function submitLearnerAttempt(request: Request, env: WorkerEnv, attemptId: string): Promise<Response> {
  const parsed = await readBoundedJson(request, 128);
  if (!parsed.ok) return parsed.response;
  if (!hasOnlyEmptyObject(parsed.body)) return jsonResponse({ error: "invalid_attempt_submission" }, 400);

  const auth = await authenticatedCaller(request, env);
  if (!auth.context) return auth.response!;
  const roleDenied = await requireActiveRole(auth.context, "student");
  if (roleDenied) {
    const audit = roleDenied.status === 403
      ? await auditPrivilegedWriteOutcome(
          auth.context, "student_attempt_submit", attemptId, "denied",
        )
      : null;
    return audit ?? roleDenied;
  }

  const { data, error } = await auth.context.supabase.rpc("submit_attempt", {
    p_attempt_id: attemptId,
  });
  if (error) {
    const auditOutcome = classifyPrivilegedWriteError(error);
    const audit = await auditPrivilegedWriteOutcome(
      auth.context, "student_attempt_submit", attemptId,
      auditOutcome.outcome, auditOutcome.failureCategory,
    );
    if (audit) return audit;
    if (error.message === "attempt_not_found") return jsonResponse({ error: "attempt_not_found" }, 404);
    if (error.message === "attempt_not_in_progress") return jsonResponse({ error: "attempt_not_editable" }, 409);
    if (error.message === "attempt_response_required") return jsonResponse({ error: "attempt_response_required" }, 409);
    if (error.message === "attempt_submission_forbidden") return jsonResponse({ error: "attempt_submission_forbidden" }, 403);
    return jsonResponse({ error: "attempt_submission_failed" }, 500);
  }
  const submitted = asRows(data)[0];
  if (!submitted) return jsonResponse({ error: "attempt_submission_failed" }, 500);
  return jsonResponse({ attempt: submitted });
}

async function linkTimedAttemptToAssessmentSubmission(
  request: Request,
  env: WorkerEnv,
  attemptId: string,
): Promise<Response> {
  const parsed = await readBoundedJson(request, 1_024);
  if (!parsed.ok) return parsed.response;
  if (!isUuid(attemptId) || !hasOnlyTimedAttemptAssessmentLinkFields(parsed.body)) {
    return jsonResponse({ error: "invalid_timed_attempt_assessment_link" }, 400);
  }

  const auth = await authenticatedCaller(request, env);
  if (!auth.context) return auth.response!;
  const roleDenied = await requireActiveRole(auth.context, "student");
  if (roleDenied) {
    if (roleDenied.status === 403) {
      const audit = await auditPrivilegedWriteOutcome(
        auth.context, "student_timed_attempt_assessment_link", attemptId, "denied",
      );
      if (audit) return audit;
    }
    return roleDenied;
  }

  const requestBody = parsed.body as TimedAttemptAssessmentLinkRequest;
  const { data, error } = await auth.context.supabase.rpc(
    "link_timed_attempt_assessment_submission",
    {
      p_attempt_id: attemptId,
      p_assessment_submission_id: requestBody.assessment_submission_id,
      p_idempotency_key: requestBody.idempotency_key,
    },
  );

  if (error) {
    const auditOutcome = classifyPrivilegedWriteError(error);
    const audit = await auditPrivilegedWriteOutcome(
      auth.context,
      "student_timed_attempt_assessment_link",
      attemptId,
      auditOutcome.outcome,
      auditOutcome.failureCategory,
    );
    if (audit) return audit;

    if (error.message === "timed_attempt_assessment_link_forbidden") {
      return jsonResponse({ error: "timed_attempt_assessment_link_forbidden" }, 403);
    }
    if (error.message === "attempt_not_found" ||
        error.message === "assessment_submission_not_found") {
      return jsonResponse({ error: error.message }, 404);
    }
    if ([
      "attempt_not_submitted",
      "attempt_task_version_mismatch",
      "timed_attempt_assessment_link_conflict",
      "timed_attempt_assessment_link_idempotency_conflict",
      "assessment_submission_not_linkable",
      "attempt_not_linkable",
    ].includes(error.message)) {
      return jsonResponse({ error: error.message }, 409);
    }
    if (error.message === "invalid_timed_attempt_assessment_link") {
      return jsonResponse({ error: error.message }, 400);
    }
    return jsonResponse({ error: "timed_attempt_assessment_link_failed" }, 500);
  }

  const linked = asRows(data)[0];
  if (!linked) return jsonResponse({ error: "timed_attempt_assessment_link_failed" }, 500);
  return jsonResponse(
    { link: linked },
    linked.is_replay === true ? 200 : 201,
  );
}

async function listLearnerSubmissions(request: Request, env: WorkerEnv): Promise<Response> {
  const auth = await authenticatedCaller(request, env);
  if (!auth.context) return auth.response!;
  const roleDenied = await requireActiveRole(auth.context, "student");
  if (roleDenied) {
    const audit = await auditProtectedReadOutcome(
      auth.context, "student_submission_list_authorized", undefined, "denied", roleDenied,
    );
    return audit ?? roleDenied;
  }

  const [{ data: submissions, error: submissionsError }, { data: enrolments, error: enrolmentsError }] =
    await Promise.all([
      auth.context.supabase
        .from("assessment_submissions")
        .select("id, learner_id, task_version_id, rubric_version_id, response_mode, status, accepted_at, grading_due_at, sla_target_seconds, capacity_limit_snapshot, open_submissions_before_acceptance, task_versions(task_code, title, version, pdf_response_enabled, expected_min_words, ideal_words), submission_versions(id, version_number, word_count, created_at)")
        .eq("learner_id", auth.context.userId)
        .order("accepted_at", { ascending: false })
        .order("id", { ascending: false }),
      auth.context.supabase
        .from("course_enrolments")
        .select("pathway_id")
        .eq("learner_id", auth.context.userId)
        .eq("status", "active"),
    ]);

  if (submissionsError || enrolmentsError) {
    const audit = await auditProtectedReadOutcome(
      auth.context, "student_submission_list_authorized", undefined, "failed",
    );
    if (audit) return audit;
    return jsonResponse({ error: "assessment_submissions_unavailable" }, 500);
  }

  const pathwayIds = Array.from(new Set(
    (enrolments ?? [])
      .map((enrolment) => enrolment.pathway_id)
      .filter((pathwayId): pathwayId is string => typeof pathwayId === "string"),
  ));
  let availableTasks: Array<{
    id: string;
    task_code: string;
    title: string;
    version: number;
    expected_min_words: number;
    ideal_words: number;
    pdf_response_enabled: boolean;
  }> = [];

  if (pathwayIds.length > 0) {
    const { data: tasks, error: tasksError } = await auth.context.supabase
      .from("task_versions")
      .select("id, task_code, title, version, expected_min_words, ideal_words, pdf_response_enabled")
      .in("pathway_id", pathwayIds)
      .eq("release_state", "published")
      .order("title", { ascending: true })
      .order("id", { ascending: true });

    if (tasksError) {
      const audit = await auditProtectedReadOutcome(
        auth.context, "student_submission_list_authorized", undefined, "failed",
      );
      if (audit) return audit;
      return jsonResponse({ error: "assessment_tasks_unavailable" }, 500);
    }
    availableTasks = tasks ?? [];
  }

  const audit = await auditProtectedReadOutcome(
    auth.context, "student_submission_list_authorized", undefined, "success",
  );
  if (audit) return audit;
  return jsonResponse({
    submissions: submissions ?? [],
    available_tasks: availableTasks,
  });
}

async function acceptLearnerSubmission(request: Request, env: WorkerEnv): Promise<Response> {
  const parsed = await readBoundedJson(request, 24_576);
  if (!parsed.ok) return parsed.response;
  if (!hasOnlyAssessmentSubmissionFields(parsed.body)) {
    return jsonResponse({ error: "invalid_assessment_submission" }, 400);
  }

  const auth = await authenticatedCaller(request, env);
  if (!auth.context) return auth.response!;
  const roleDenied = await requireActiveRole(auth.context, "student");
  if (roleDenied) {
    const audit = roleDenied.status === 403
      ? await auditPrivilegedWriteOutcome(
          auth.context, "student_assessment_submission_accept",
          parsed.body.task_version_id, "denied",
        )
      : null;
    return audit ?? roleDenied;
  }

  const { data, error } = await auth.context.supabase.rpc("accept_assessment_submission", {
    p_task_version_id: parsed.body.task_version_id,
    p_idempotency_key: parsed.body.idempotency_key,
    p_response_text: parsed.body.response_text,
  });

  if (error) {
    const auditOutcome = classifyPrivilegedWriteError(error);
    const audit = await auditPrivilegedWriteOutcome(
      auth.context, "student_assessment_submission_accept",
      parsed.body.task_version_id, auditOutcome.outcome, auditOutcome.failureCategory,
    );
    if (audit) return audit;
    if (error.message === "assessment_submission_forbidden") {
      return jsonResponse({ error: "assessment_submission_forbidden" }, 403);
    }
    if (error.message === "invalid_assessment_submission") {
      return jsonResponse({ error: "invalid_assessment_submission" }, 400);
    }
    if (error.message === "assessment_task_not_available") {
      return jsonResponse({ error: "assessment_task_not_available" }, 404);
    }
    if (error.message === "submission_capacity_unavailable") {
      return jsonResponse({ error: "submission_capacity_unavailable" }, 503);
    }
    if (error.message === "submission_capacity_full") {
      return jsonResponse({ error: "submission_capacity_full" }, 409);
    }
    if (error.message === "submission_idempotency_conflict") {
      return jsonResponse({ error: "submission_idempotency_conflict" }, 409);
    }
    return jsonResponse({ error: "assessment_submission_failed" }, 500);
  }

  const accepted = asRows(data)[0];
  if (!accepted) return jsonResponse({ error: "assessment_submission_failed" }, 500);
  // This route only accepts the typed mode; return it explicitly so callers
  // receive the same response contract as optional-PDF and PDF-only routes.
  return jsonResponse(
    { submission: { ...accepted, response_mode: "typed" } },
    accepted.is_replay === true ? 200 : 201,
  );
}

